ALTER TABLE "plan_requests" DROP CONSTRAINT "plan_input";--> statement-breakpoint
ALTER TABLE "planning_runs" DROP CONSTRAINT "planning_versions";--> statement-breakpoint
ALTER TABLE "planning_runs" DROP CONSTRAINT "planning_result";--> statement-breakpoint
ALTER TABLE "plan_requests" ADD CONSTRAINT "plan_input" CHECK (coalesce(jsonb_typeof("plan_requests"."input")='object' AND "plan_requests"."input"->>'schema_version' in ('1','2') AND octet_length("plan_requests"."input"::text) between 1 and 65536,false));--> statement-breakpoint
ALTER TABLE "planning_runs" ADD CONSTRAINT "planning_versions" CHECK (coalesce("planning_runs"."versions"->>'workflowVersion' in ('planning-workflow-1','planning-workflow-2') AND octet_length("planning_runs"."versions"::text)<=2097152 AND "planning_runs"."versions_hash" ~ '^[a-f0-9]{64}$',false));--> statement-breakpoint
ALTER TABLE "planning_runs" ADD CONSTRAINT "planning_result" CHECK (coalesce(("planning_runs"."status"='completed' AND "planning_runs"."result" is not null AND "planning_runs"."result_hash" ~ '^[a-f0-9]{64}$' AND "planning_runs"."result"->>'kind'=(CASE "planning_runs"."versions"->>'workflowVersion' WHEN 'planning-workflow-2' THEN 'rotation_assessment' ELSE 'planning_assessment' END) AND octet_length("planning_runs"."result"::text)<=8388608) OR ("planning_runs"."status"<>'completed' AND "planning_runs"."result" is null AND "planning_runs"."result_hash" is null),false));